1	689 scripts/index.src.tpl
2	<!doctype html>
3	<html lang="en"><head><meta charset="utf-8"><title>FirstRun demo</title>
4	<script src="assets/gsap.min.js"></script>
5	<style>
6	@font-face{font-family:'Geist';src:url('assets/fonts/Geist.woff2') format('woff2');font-weight:100 900;font-style:normal}
7	@font-face{font-family:'Geist Mono';src:url('assets/fonts/GeistMono.woff2') format('woff2');font-weight:100 900;font-style:normal}
8	:root{--bg:#F4F5F9;--card:#FFFFFF;--ink:#1D1D1F;--muted:#65656B;--line:#D8D8DE;--soft:#ECECF1;--pass:#1B8A3A;--fail:#C4281C;--accent:#0A66D6;--amber:#B25E00;
9	--accent-soft:#E7F0FC;--pass-soft:#E6F3EA;--fail-soft:#FBE9E7;--shadow:0 1px 2px rgba(29,29,31,.05),0 24px 60px -20px rgba(29,29,31,.20)}
10	*{box-sizing:border-box;margin:0;padding:0}
11	html,body{width:1920px;height:1080px;overflow:hidden;background:var(--bg);color:var(--ink);font-family:'Geist',sans-serif;-webkit-font-smoothing:antialiased}
12	#root{position:relative;width:1920px;height:1080px;overflow:hidden;background:var(--bg)}
13	#bg{position:absolute;inset:0;background:radial-gradient(ellipse 70% 60% at 50% 42%,#FFFFFF 0%,rgba(255,255,255,0) 70%)}
14	.mono{font-family:'Geist Mono',monospace}
15	.scene{position:absolute;inset:0;opacity:0}
16	.content{position:absolute;inset:0}
17	.center{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:36px;padding:120px 140px 200px}
18	.card{background:var(--card);border:1px solid rgba(29,29,31,.08);border-radius:26px;box-shadow:var(--shadow)}
19	.h1{font-weight:700;font-size:76px;line-height:1.05;letter-spacing:-.045em;text-align:center}
20	.h2{font-weight:700;font-size:54px;line-height:1.08;letter-spacing:-.035em}
21	.sub{font-size:36px;line-height:1.25;letter-spacing:-.02em;color:var(--muted);text-align:center}
22	.kick{font-size:24px;font-weight:600;letter-spacing:.02em;color:var(--muted);text-transform:uppercase}
23	/* label */
24	.lab{position:absolute;left:56px;top:40px;display:flex;align-items:center;gap:14px;padding:10px 22px 10px 12px;border-radius:999px;background:var(--card);border:1px solid rgba(29,29,31,.08);box-shadow:0 1px 2px rgba(29,29,31,.06),0 10px 30px -12px rgba(29,29,31,.18);font-size:26px;font-weight:600;letter-spacing:-.01em;opacity:0;z-index:20}
25	.lab .lg{width:40px;height:40px;border-radius:10px;display:block;object-fit:contain}
26	.lab .lg.chipw{background:#fff;border:1px solid var(--line);padding:6px}
27	.lab .dotc{width:14px;height:14px;border-radius:50%;background:var(--accent);margin:0 6px 0 10px}
28	.lab .sep{color:var(--muted);font-weight:400}
29	.lab .pt{color:var(--accent)}
30	.lab .dots{display:flex;gap:7px;margin-left:10px}
31	.lab .dots i{width:11px;height:11px;border-radius:50%;background:var(--line);display:block}
32	.lab .dots i.on{background:var(--accent)}
33	.lab .dots i.done{background:var(--pass)}
34	/* captions */
35	#caps{position:absolute;left:0;right:0;bottom:48px;height:130px;z-index:30;pointer-events:none}
36	.cp{position:absolute;left:50%;bottom:0;transform:translateX(-50%);max-width:1480px;width:max-content;text-align:center;font-size:40px;line-height:1.28;font-weight:600;letter-spacing:-.015em;color:var(--ink);background:rgba(255,255,255,.97);padding:14px 34px 16px;border-radius:24px;box-shadow:0 1px 2px rgba(29,29,31,.08),0 14px 36px -14px rgba(29,29,31,.28);border:1px solid rgba(29,29,31,.07);opacity:0}
37	/* plate frame */
38	.pf{position:absolute;overflow:hidden;border-radius:22px;background:#fff;border:1px solid rgba(29,29,31,.10);box-shadow:var(--shadow)}
39	.pf .cam{position:absolute;left:0;top:0;transform-origin:0 0}
40	.pf .cam img{display:block}
41	.ring{position:absolute;border:7px solid var(--accent);border-radius:16px;box-shadow:0 0 0 9999px rgba(29,29,31,0);opacity:0}
42	.ring.red{border-color:var(--fail)}
43	.ring.green{border-color:var(--pass)}
44	.dim{position:absolute;inset:0;background:rgba(29,29,31,.0);pointer-events:none}
45	.tag{position:absolute;display:flex;align-items:center;gap:12px;padding:12px 22px;border-radius:16px;background:var(--card);box-shadow:var(--shadow);border:1px solid rgba(29,29,31,.08);font-size:28px;font-weight:600;letter-spacing:-.01em;white-space:nowrap;opacity:0}
46	.tag.red{color:var(--fail)}
47	.tag.green{color:var(--pass)}
48	.tag.blue{color:var(--accent)}
49	.tag small{font-size:22px;color:var(--muted);font-weight:500}
50	.src{position:absolute;font-size:19px;color:var(--muted);white-space:nowrap}
51	/* icons */
52	.ic{width:32px;height:32px;flex:none}
53	.ic circle{fill:var(--pass)}
54	.ic path{stroke:#fff;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round}
55	.ic.bad circle{fill:var(--fail)}
56	.ic.fix circle{fill:var(--accent)}
57	/* terminal */
58	.term{padding:0 0 26px}
59	.term .bar{display:flex;align-items:center;gap:10px;padding:20px 28px;border-bottom:1px solid var(--soft)}
60	.term .bar i{width:14px;height:14px;border-radius:50%;display:block}
61	.term .bar .t{margin-left:16px;font-size:20px;color:var(--muted)}
62	.tl{display:flex;align-items:center;gap:20px;padding:14px 40px 0;font-size:29px}
63	.tl .cmd{flex:1;color:var(--ink);white-space:nowrap}
64	.tl .cmd b{color:var(--muted);font-weight:400}
65	.tl .st{display:flex;align-items:center;gap:12px;font-size:23px;color:var(--pass);font-weight:500;white-space:nowrap}
66	.tl .st.bad{color:var(--fail)}
67	.tl.err{font-size:25px;color:var(--fail);padding-top:8px}
68	.tl.note{font-size:23px;color:var(--muted);padding-top:10px}
69	/* wordmark */
70	.wm{font-family:'Geist Mono',monospace;font-weight:600;letter-spacing:-.04em;display:flex;align-items:center;gap:.06em}
71	.wm .cur{display:inline-block;width:.52em;height:.86em;background:var(--accent);border-radius:.04em}
72	/* track */
73	.track{position:relative;width:1380px;height:150px}
74	.track .ln{position:absolute;left:30px;right:30px;top:30px;height:4px;background:var(--line);border-radius:2px}
75	.nd{position:absolute;top:0;width:64px;height:64px;border-radius:50%;background:var(--card);border:3px solid var(--line);display:flex;align-items:center;justify-content:center;font-size:24px;font-weight:600;color:var(--muted)}
76	.nd.ok{background:var(--pass);border-color:var(--pass);color:#fff}
77	.nd.bad{background:var(--fail);border-color:var(--fail);color:#fff}
78	.dev{position:absolute;top:-70px;left:2px;display:flex;flex-direction:column;align-items:center;gap:8px}
79	.dev .tg{font-size:21px;font-weight:600;color:var(--accent);background:var(--accent-soft);padding:5px 14px;border-radius:999px;white-space:nowrap}
80	.dev .dt{width:20px;height:20px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 6px rgba(10,102,214,.18)}
81	/* flow diagram */
82	.flow{display:flex;align-items:stretch;gap:0}
83	.fn{width:206px;padding:22px 18px;display:flex;flex-direction:column;gap:10px;align-items:flex-start}
84	.fn .k{font-size:19px;font-weight:600;color:var(--muted);letter-spacing:.04em;text-transform:uppercase}
85	.fn .n{font-size:29px;font-weight:700;letter-spacing:-.03em;line-height:1.1}
86	.fn .d{font-size:19px;color:var(--muted);line-height:1.3}
87	.fn.hot{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft),var(--shadow)}
88	.ar{width:34px;display:flex;align-items:center;justify-content:center;color:#B0B0B8;font-size:30px}
89	/* diff */
90	.diff{width:1240px;padding:0 0 18px}
91	.diff .hd{padding:18px 28px;border-bottom:1px solid var(--soft);font-size:21px;color:var(--muted);display:flex;justify-content:space-between}
92	.dl{display:flex;gap:24px;padding:14px 28px;font-size:34px;align-items:center}
93	.dl.del{background:var(--fail-soft);color:#8E1B12}
94	.dl.add{background:var(--pass-soft);color:#11602A}
95	.dl .sg{width:24px;font-weight:700}
96	.dl.ctx{color:var(--muted);font-size:24px;font-family:'Geist',sans-serif}
97	/* tiles */
98	.tiles{display:flex;gap:28px}
99	.tile{width:380px;padding:30px 32px;display:flex;flex-direction:column;gap:8px}
100	.tile .v{font-size:64px;font-weight:700;letter-spacing:-.04em;line-height:1}
101	.tile .l{font-size:23px;color:var(--muted);line-height:1.3}
102	.tile.g .v{color:var(--pass)}
103	/* bisect */
104	.bis{position:relative;width:1560px;height:420px}
105	.bis .ax{position:absolute;left:40px;right:40px;top:150px;height:4px;background:var(--line);border-radius:2px}
106	.rel{position:absolute;top:118px;width:200px;margin-left:-100px;display:flex;flex-direction:column;align-items:center;gap:10px}
107	.rel .o{width:68px;height:68px;border-radius:50%;border:3px solid var(--line);background:#fff;display:flex;align-items:center;justify-content:center}
108	.rel.ok .o{background:var(--pass);border-color:var(--pass)}
109	.rel.bad .o{background:var(--fail);border-color:var(--fail)}
110	.rel .v{font-size:32px;font-weight:700;letter-spacing:-.02em}
111	.rel .d{font-size:20px;color:var(--muted)}
112	.rel .t{font-size:20px;font-weight:600;padding:4px 12px;border-radius:999px;white-space:nowrap}
113	.rel.ok .t{color:#197E35;background:var(--pass-soft)}
114	.rel.bad .t{color:var(--fail);background:var(--fail-soft)}
115	.guide{position:absolute;top:96px;left:1420px;width:260px;margin-left:-130px;display:flex;flex-direction:column;align-items:center;gap:10px}
116	.guide .pin{width:6px;height:120px;background:var(--ink);border-radius:3px}
117	.guide .v{font-size:28px;font-weight:700;text-align:center;line-height:1.15}
118	.guide .d{font-size:20px;color:var(--muted)}
119	.gap{position:absolute;top:30px;height:40px;border:3px solid var(--fail);border-bottom:none;border-radius:14px 14px 0 0}
120	.gap .t{position:absolute;left:50%;top:-56px;transform:translateX(-50%);font-size:34px;font-weight:700;color:var(--fail);white-space:nowrap}
121	/* pr grid */
122	.prg{position:absolute;left:150px;top:132px;width:1620px;display:grid;grid-template-columns:1fr 1fr;gap:28px 36px}
123	.prc{display:flex;flex-direction:column;gap:10px}
124	.prc .pf{position:relative;width:792px;height:330px}
125	.prc .r{font-size:22px;font-weight:600;color:var(--ink);display:flex;gap:12px;align-items:center}
126	.prc .r span{color:var(--muted);font-weight:500}
127	/* span tree */
128	.spt{width:860px;padding:30px 36px}
129	.sp{display:flex;align-items:center;gap:16px;height:52px;font-size:28px}
130	.sp .nm{font-family:'Geist Mono',monospace}
131	.sp .kd{font-family:'Geist Mono',monospace;font-size:18px;font-weight:600;padding:4px 10px;border-radius:8px;letter-spacing:.04em}
132	.kd.w{background:#EEF0F6;color:#3A3A42}.kd.a{background:#F1EAFB;color:#6B34B5}.kd.t{background:#E7F0FC;color:#0A4FA8}.kd.g{background:#E6F3EA;color:#11602A}
133	.sp .bar2{height:14px;border-radius:5px;background:var(--accent);opacity:.75;margin-left:auto}
134	/* code */
135	.code{width:940px;padding:0 0 22px}
136	.code .hd{padding:18px 28px;border-bottom:1px solid var(--soft);font-size:21px;color:var(--muted)}
137	.code pre{font-family:'Geist Mono',monospace;font-size:27px;line-height:1.55;padding:20px 32px 0;color:var(--ink);white-space:pre}
138	.code .k1{color:#6B34B5}.code .s1{color:#11602A}.code .c1{color:var(--muted)}
139	/* stat */
140	.stat{padding:34px 40px;display:flex;flex-direction:column;gap:10px}
141	.stat .v{font-size:96px;font-weight:700;letter-spacing:-.05em;line-height:1}
142	.stat .l{font-size:26px;color:var(--muted);line-height:1.3}
143	.cmp{padding:30px 36px;display:flex;flex-direction:column;gap:18px;width:560px}
144	.cmp .t{font-size:26px;font-weight:700;letter-spacing:-.02em}
145	.cmp .row{display:flex;align-items:center;gap:16px;font-size:23px}
146	.cmp .row .k{width:60px;color:var(--muted);font-weight:600}
147	.cmp .row .tr{flex:1;height:30px;background:var(--soft);border-radius:8px;position:relative;overflow:hidden}
148	.cmp .row .tr i{position:absolute;left:0;top:0;bottom:0;border-radius:8px;background:var(--muted);transform-origin:left center}
149	.cmp .row.v2 .tr i{background:var(--pass)}
150	.cmp .row .n{width:90px;text-align:right;font-weight:700}
151	/* end */
152	.tagline{font-size:80px;font-weight:700;letter-spacing:-.05em}
153	.tagline .lit{color:var(--accent)}
154	.built{display:flex;align-items:center;gap:30px;font-size:28px;color:var(--muted)}
155	.built .lgw{display:flex;align-items:center;gap:14px;color:var(--ink);font-weight:600}
156	.built .lgw img{width:52px;height:52px;border-radius:13px;object-fit:contain}
157	.built .lgw img.chipw{background:#fff;border:1.5px solid var(--line);padding:9px}
158	.urls{display:flex;gap:18px}
159	.url{font-family:'Geist Mono',monospace;font-size:25px;padding:12px 22px;border-radius:999px;background:#fff;border:1px solid rgba(29,29,31,.08);box-shadow:0 1px 2px rgba(29,29,31,.05)}
160	.me{display:flex;align-items:center;gap:16px;font-size:24px;color:var(--muted)}
161	.me img{width:60px;height:60px;border-radius:50%;object-fit:cover;border:3px solid #fff;box-shadow:0 6px 20px -6px rgba(29,29,31,.3)}
162	.me b{color:var(--ink)}
163	.toolhead{display:flex;align-items:center;gap:26px}
164	.toolhead img{width:110px;height:110px;border-radius:26px;object-fit:contain}
165	.toolhead img.chipw{background:#fff;border:1.5px solid var(--line);padding:18px}
166	.toolhead .nm{font-size:84px;font-weight:700;letter-spacing:-.045em}
167	</style></head><body>
168	<div id="root" data-composition-id="firstrun-demo" data-start="0" data-duration="179" data-width="1920" data-height="1080">
